const brands=[
 {id:'tsukada',name:'塚田農場',en:'TSUKADA NOJO',tag:'大地の恵みを、にぎわいの真ん中へ。',image:'jidori.png',alt:'炭火で焼き上げた地鶏',category:'地鶏・郷土料理',food:'地鶏炭火焼',region:'miyazaki',story:'jidori',site:'https://www.tsukadanojo.jp/',store:'https://shop.tsukadanojo.jp/',intro:'宮崎の地鶏と、九州の郷土料理。産地のおいしさを、気の置けない仲間と囲む食卓へ。',origin:'宮崎県の塚田地区にある自社養鶏場。その名前を受け継いだ店が、塚田農場です。生産者と店をつなぐ仕組みを育てながら、地鶏をもっと身近に楽しめる食へと届けてきました。',foodText:'炭火の香りをまとった地鶏を、熱いうちに。一皿をみんなで囲めば、その土地の話も、今日の話も、自然とはずむ。',reason:'気の置けない人と、にぎやかに一皿を囲みたい。そんな気分に、地鶏炭火焼と九州の味を楽しむ塚田農場を。'},
 {id:'yonpachi',name:'四十八漁場',en:'YONPACHI GYOJOU',tag:'海の今日を、いただきます。',image:'fish.jpg',alt:'四十八漁場の刺身の盛り合わせ',category:'鮮魚・日本酒',food:'鮮魚のお刺身',region:'sea',story:'sea',site:'https://www.48gyojyou.com/',store:'https://www.48gyojyou.com/',intro:'全国の漁師や漁協、産地市場とつながり、魚と日本酒を楽しむ。まだ知らない海のおいしさに出会う場所。',origin:'魚を食べる楽しみを、未来にもつなぎたい。四十八漁場は、そんな想いを店名に込めたブランドです。産地と直接つながり、魚の手当てから流通まで、おいしさを届ける道のりを大切にしています。',foodText:'その日の出会いを、お刺身から。魚の種類も、味わいも、産地も、一皿をきっかけにもっと知りたくなる。内容は店舗・時期・水揚げによって異なります。',reason:'旬の味や、まだ知らない食材との出会いを楽しみたい。そんな気分には、産地とつながる鮮魚と日本酒の四十八漁場を。'},
 {id:'yakitori',name:'焼鳥つかだ',en:'YAKITORI TSUKADA',tag:'一本に向き合う、豊かな時間。',image:'yakitori-a.jpg',alt:'炭火で一本ずつ焼き上げる焼鳥',category:'地鶏・焼鳥',food:'みやざき地頭鶏の焼鳥',region:'miyazaki',story:'craft',site:'https://www.yakitori-tsukada.jp/',store:'https://www.yakitori-tsukada.jp/',intro:'みやざき地頭鶏を、職人が炭火で丹念に。地鶏の持ち味を、一本ずつゆっくりと味わう。',origin:'生販直結で培った地鶏への知識と、焼鳥という表現が出会う場所。焼鳥つかだは、産地とつながるAPの土台から、地鶏を楽しむもう一つの時間をつくっています。',foodText:'串打ちから火入れまで、一本ごとに手をかける。素材と炭火に向き合う仕事を、目の前の焼鳥から感じてください。',reason:'少し落ち着いた空間で、料理をじっくり味わいたい。そんな気分に、職人の炭火仕事を楽しむ焼鳥つかだを。'}
];
const pillars=['食をつくる','産地とつくる','店をつくる','人とつくる','未来をつくる'];
const stories=[
 {id:'jidori',category:0,no:'01',title:'一羽の地鶏が、塚田農場の一皿になるまで。',image:'flame.png',alt:'地鶏を焼き上げる炭火の炎',sub:'産地と厨房をつなぐ、おいしさの道のり。',brand:'tsukada',intro:'高く上がる炎。香ばしい一皿。そのおいしさは、厨房だけで生まれたものではありません。地鶏を育てる日々から食卓までをたどると、APが大切にする「生販直結」が見えてきます。',sections:[['01　はじまりは、一羽を育てること。','地鶏炭火焼の物語は、鶏を育てるところから始まります。親鳥、ヒナ、そして契約農家での飼育。食材を仕入れるだけでは見えてこない長い時間が、一皿の前にあります。','chickens.png'],['02　産地の仕事を、店につなぐ。','育てる人と、料理する人がつながっていること。APの生販直結は、生産から加工・流通・販売までを一貫して考える仕組みです。産地の価値を受け取り、お客様まで届ける。その道筋もまた、おいしさの一部です。','farm.png'],['03　最後の仕事は、炭と炎。','届いた地鶏を焼き上げるのは、厨房の人の手。炭の状態を見て、炎を扱い、仕上がりを見極める。育てる仕事から焼く仕事へとつながってきた一羽が、ここで一皿になります。','jidori.png']],ending:'食べるとき、少しだけ産地を思い浮かべてみる。いつもの一皿が、違って見えるかもしれません。'},
 {id:'sea',category:1,no:'02',title:'魚のおいしさは、海の上から始まっている。',image:'fish.jpg',alt:'四十八漁場の鮮魚',sub:'四十八漁場から、海へ。',brand:'yonpachi',intro:'お刺身の向こう側には、漁師の仕事があります。四十八漁場は全国の産地とつながり、魚のおいしさを食卓まで届けています。',sections:[['見えない仕事が、味になる。','水揚げされた魚に、どんな手当てをするか。どう運ぶか。四十八漁場では、船上から始まる処理と独自の流通を大切にしています。鮮魚の価値を、産地から店までつないでいます。','fish.jpg'],['知らない魚に出会う楽しみ。','都心ではあまり見かけない魚も、味わえば発見になる。食べる魚の選択肢が広がることは、海と食卓の関係を考えるきっかけにもなります。次の一皿で、産地の話を聞いてみませんか。',null]],ending:'今日おいしかった魚を、未来も楽しめるように。食べることから始まる関係があります。'},
 {id:'craft',category:0,no:'03',title:'同じ地鶏が、違う一皿になる理由。',image:'yakitori-a.jpg',alt:'焼鳥つかだの炭火調理',sub:'焼鳥つかだの、一本と向き合う仕事。',brand:'yakitori',intro:'豪快な炭火焼と、丹念に焼き上げる焼鳥。同じ産地の食材から、違う食体験が生まれます。ブランドの多様さは、食材の可能性の多様さでもあります。',sections:[['一本の、その手前に。','焼く前に、切り分け、串を打つ。一本の焼鳥には、目に見えない準備があります。みやざき地頭鶏の魅力をどう引き出すか。職人の手が、食材とお客様をつなぎます。','yakitori-c.jpg'],['その場で味わう時間まで。','料理を食べる空間、会話の距離、炭火の気配。焼鳥つかだが届けるのは、一本の焼鳥と、それを楽しむ時間。産地の価値は、店という場所で新しい表情を見せます。','yakitori-b.jpg']],ending:'ひとつの素材に、ひとつの答えだけではない。だから、APのブランドを巡ることは面白い。'},
 {id:'brand',category:2,no:'04',title:'ひとつの思想から、いくつもの食卓が生まれる。',image:'yakitori-b.jpg',alt:'焼鳥つかだの店内',sub:'ブランドの違いから、APを知る。',brand:'yakitori',intro:'塚田農場、四十八漁場、焼鳥つかだ。食も、空間も、過ごし方も違う。その背景には、食の価値をどう届けるかという共通の問いがあります。',sections:[['ブランドは、食の楽しみ方。','仲間と地鶏を囲む日もあれば、魚と日本酒を味わう日もある。一本の焼鳥にゆっくり向き合う夜もある。多様なブランドは、食と人が出会う入口を増やしています。',null],['店の向こうに、産地がある。','表現が変わっても、素材に向き合うことは変わりません。気になったブランドから料理をたどり、産地を知る。ひとつの店から、APの世界が広がっていきます。','farm.png']],ending:'今日は、どんな食の時間を過ごしますか。'},
 {id:'people',category:3,no:'05',title:'料理を届ける人は、産地の物語も届けている。',image:'fictional-chef.png',alt:'デモ用架空人物・高橋直人のAI生成画像',sub:'食をつくる仕事を考える、人物編集サンプル。',brand:'tsukada',intro:'食の仕事は、皿の上だけには収まりません。素材を知り、作り手を知り、お客様に伝える。架空の料理人・高橋直人のストーリーから、その仕事を描きます。',sections:[['おいしい理由を、自分の言葉で。','「どう育った食材なのか。それを知ると、料理の扱い方も、伝え方も変わる気がします」。デモ用の架空人物・高橋直人は、そう語る料理人として設定しました。食と産地と人をつなぐ人物記事の見本です。',null]],ending:'人物と出会うと、一皿の見え方も変わる。次は、この食をつくる人のページへ。'},
 {id:'future',category:4,no:'06',title:'食の未来は、産地の未来とつながっている。',image:'farm.png',alt:'塚田農場公式サイトに掲載された契約農家の皆さん',sub:'FOOD CREATIVE FIRM、その先にあるもの。',brand:'yonpachi',intro:'おいしいものを、これからも楽しめること。そのために、食文化、飲食人、生産地の未来を一緒に考える。APが掲げるFOOD CREATIVE FIRMという姿を、身近な食から見つめます。',sections:[['つくる人が、続けられること。','食卓に料理がある。その当たり前の手前には、生産者の営みがあります。生産と販売がつながる仕組みを持つAPの活動は、産地と店を別々に考えない視点につながっています。',null],['おいしいを、次の世代へ。','魚食を未来につなぐ四十八漁場。地鶏の可能性を広げるブランド。食の課題を、具体的な店と料理から考える。その積み重ねが、未来を語る入口になります。','fish.jpg']],ending:'これは新しい事業計画の発表ではなく、公式の思想をもとにした編集企画です。'}
];
const questions=[{title:'今日は、どんな時間にしたい？',options:['気の置けない仲間と、にぎやかに','おいしい発見を、誰かと分かち合う','落ち着いて、一皿ずつ楽しむ']},{title:'今、心が動くのは？',options:['炭火の香りと、力強い地鶏','その日に出会う、海の恵み','職人が焼く、こだわりの一本']},{title:'食事に、もうひとつ求めるなら？',options:['自然と会話がはずむこと','季節や産地を感じること','つくる人の仕事を感じること']}];
